import{_ as t,o as n,c as r,j as e,a,aa as o}from"./chunks/framework.BAs_AphD.js";const f=JSON.parse('{"title":"Signing Other Entries with an Electronic Certificate","description":"","frontmatter":{"title":"Signing Other Entries with an Electronic Certificate","wiki":"en:diary:signingother"},"headers":[],"relativePath":"en/diary/signingother.md","filePath":"en/diary/signingother.md","lastUpdated":1794388980000}'),s={name:"en/diary/signingother.md"};function c(h,i,d,l,g,p){return n(),r("div",null,[...i[0]||(i[0]=[e("h1",{id:"signing-other-entries-with-an-electronic-certificate",tabindex:"-1"},[a("Signing Other Entries with an Electronic Certificate "),e("a",{class:"header-anchor",href:"#signing-other-entries-with-an-electronic-certificate","aria-label":'Permalink to "Signing Other Entries with an Electronic Certificate"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/8HrtP009bpY",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),o('<p>As with the paper version of the diary, each authorized person who has added a record to the Other Entries section in Buildary is required to sign their own record. An electronic signature is used for this purpose. If the author of the record does not have an electronic signature, they can lock their records without an electronic signature. See <a href="/buildary-help-preview/en/diary/signingwithout">Signing Without an Electronic Certificate</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Unsigned Other Entries prevent the full-day report from being signed. When downloading the full-day report for signing, the application checks the signatures in the Other Entries section. If there is an unsigned entry in the section, the system will refuse to download the report for signing and display an error message. The only user who does not need to have their Other Records signed is the person who signs the full-day report. By signing the full-day report, they confirm all of their own entries. This check can be bypassed by disabling the <strong>Other Entries signature check</strong> option in the Project Diary Settings.</p></div><p>The electronic signing procedure is described in detail in the <a href="/buildary-help-preview/en/diary/signing">Signing and Locking a Day</a> chapter.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Please note!!! The video is outdated and shows a signing method that was previously the only available option. Since version 4.0, Buildary offers several signing methods. For details, see <a href="/buildary-help-preview/en/diary/signaturesetting">Signature Method Settings</a>.</p></div>',4)])])}const y=t(s,[["render",c]]);export{f as __pageData,y as default};
